            if (Arrays.binarySearch(
                prime, (int)consSum) >= 0)
            {

                // Update the length and prime number
                if (max_length < i - j + 1)
                {
                    max_length = i - j + 1;
                    prime_number = (int)consSum;
                }
            }
        }
    }
    return prime_number;
